#include <vector>

int running_max(std::vector<int>& values) {
    if (values.empty()) return 0;

    const std::size_t original = values.size();
    int& best = values[0];

    for (std::size_t i = 1; i < original; ++i) {
        if (values[i] > best) best = values[i];
        values.push_back(values[i] + best);
    }
    return best;
}

